# -*- coding: utf-8 -*-
"""Lote 1 · parte E: arritmias, síndromes coronarios, hipertensión, emergencias y abdomen agudo (preguntas 79-100)."""
from lote01d import Q, L

Q(a="cardiologia", cat=None, tema="Control de la frecuencia en fibrilación auricular", año=2018, ext=False,
  e="Varón de 48 años hipertenso, ingresa a emergencia por palpitaciones, síncope y disnea. Examen: despierto, taquipneico, PA: 110/70 mmHg, FC: 140 x min, FR: 22 x min, SatO₂: 97 %. EKG: taquiarritmia de complejos angostos irregulares compatibles con fibrilación auricular. ¿Cuál es el tratamiento de elección para el control de frecuencia cardiaca?",
  o=["Lidocaína.", "Adenosina.", "Labetalol.", "Propafenona.", "Digoxina."], k="E",
  c="En la fibrilación auricular con respuesta ventricular rápida y estabilidad hemodinámica el objetivo inicial es controlar la frecuencia (meta < 110 lpm en reposo). Los fármacos habituales son los betabloqueantes (metoprolol, esmolol) y los antagonistas del calcio no dihidropiridínicos (diltiazem, verapamilo), siempre que no haya insuficiencia cardiaca con fracción de eyección reducida. Si hay insuficiencia cardiaca aguda o hipotensión, se prefieren la digoxina y la amiodarona IV, porque no deprimen la contractilidad. De las opciones, solo la digoxina es un fármaco aceptado de control de frecuencia: el labetalol no es de uso habitual en la FA, la lidocaína actúa sobre arritmias ventriculares, la adenosina no revierte la FA y la propafenona es antiarrítmico de ritmo (clase Ic) que se evita en cardiopatía estructural. La digoxina tarda en actuar y su margen terapéutico es estrecho (niveles < 1,2 ng/mL, vigilar potasio y función renal).",
  f="ESC/EACTS, guía de fibrilación auricular (2024); AHA/ACC/HRS, guía de fibrilación auricular (2023)",
  nota="Pregunta de redacción discutible (sin datos de insuficiencia cardiaca); se mantiene la clave del libro.")

Q(a="cardiologia", cat=None, tema="Clasificación universal del infarto: tipo 2", año=2018, ext=False,
  e="Varón de 52 años, diabético y con enfermedad renal crónica en hemodiálisis, presenta hemorragia digestiva alta, hipotensión y taquicardia. Hb: 5 g/dL. Evoluciona con dolor precordial opresivo y disnea. EKG: cambios compatibles con síndrome coronario agudo. Según la clasificación universal de infarto de miocardio, ¿a qué tipo corresponde?",
  o=["2.", "3.", "4.", "1.", "5."], k="A",
  c="La Cuarta Definición Universal del Infarto (2018) distingue cinco tipos: tipo 1, por ruptura o erosión de una placa aterosclerótica con trombo (el infarto «clásico»); tipo 2, por desequilibrio entre aporte y demanda de oxígeno sin trombosis aguda de la placa (anemia grave, hipotensión, taquiarritmia, espasmo, hipoxemia); tipo 3, muerte súbita cardiaca con probable infarto sin biomarcadores; tipo 4, asociado a angioplastia (4a), trombosis del stent (4b) o reestenosis (4c); tipo 5, asociado a cirugía de revascularización. Este paciente tiene una anemia de 5 g/dL por hemorragia digestiva: es un infarto tipo 2 por aumento de la demanda y disminución del aporte. El tratamiento es corregir la causa (transfundir, controlar el sangrado), no antitrombóticos agresivos ni reperfusión, que empeorarían la hemorragia.",
  f="Cuarta Definición Universal del Infarto de Miocardio (Thygesen, 2018); ESC, síndromes coronarios agudos (2023)")

Q(a="cardiologia", cat=None, tema="Antihipertensivos contraindicados en la gestante", año=2018, ext=False,
  e="¿Cuál de los siguientes fármacos está contraindicado en la gestante hipertensa?",
  o=["Inhibidores de la enzima de conversión de angiotensina II.", "Simpaticolíticos con acción central.", "Antagonistas alfa selectivos.", "Vasodilatadores directos.", "Antagonistas de los canales de calcio."], k="A",
  c="Los inhibidores de la enzima convertidora de angiotensina (IECA) y los antagonistas del receptor de angiotensina II (ARA II), y también el aliskiren, están contraindicados en el embarazo porque producen fetopatía: oligohidramnios, hipoplasia pulmonar, displasia renal, anuria neonatal, hipocalvaria y muerte fetal, sobre todo en el segundo y tercer trimestre; en el primer trimestre se asocian a malformaciones cardiovasculares y del sistema nervioso. Los fármacos seguros en la hipertensión del embarazo son la metildopa (simpaticolítico central), el labetalol, el nifedipino de liberación prolongada (calcioantagonista) y la hidralazina (vasodilatador directo, sobre todo en crisis). El tratamiento urgente de la PA ≥ 160/110 mmHg es labetalol IV, nifedipino oral o hidralazina IV. Las mujeres en edad fértil con IECA/ARA II deben recibir anticoncepción o cambio de fármaco al planificar embarazo.",
  f="ACOG, Practice Bulletin N.º 222 (2020); ISSHP (2021); MINSA/INS, GPC N.º 03-2025 de trastorno hipertensivo del embarazo (primer nivel)")

Q(a="hematologia", cat=None, tema="Control de la anticoagulación con warfarina", año=2018, ext=False,
  e="Paciente de 65 años, diagnosticado de fibrilación auricular, en tratamiento con warfarina hace 2 meses; consulta por equimosis. ¿Qué prueba solicita como control de la anticoagulación?",
  o=["Cuantificación de fibrinógeno.", "Tiempo de reptilase.", "Tiempo de tromboplastina parcial activado.", "Tiempo de trombina.", "Tiempo de protrombina (INR)."], k="E",
  c="La warfarina inhibe la vitamina K epóxido reductasa y reduce la síntesis hepática de los factores II, VII, IX y X y de las proteínas C y S. Como el factor VII tiene la vida media más corta, el efecto inicial se ve en la vía extrínseca, y se mide con el tiempo de protrombina expresado como INR (razón normalizada internacional). Rango terapéutico: INR 2-3 en fibrilación auricular y trombosis venosa, y 2,5-3,5 en prótesis valvulares mecánicas mitrales. La heparina no fraccionada se monitoriza con TTPa y la de bajo peso molecular con anti-Xa si hace falta. Una equimosis en un paciente anticoagulado requiere medir el INR de inmediato: si es > 4,5-10 sin sangrado se suspende la dosis y se da vitamina K oral; si hay sangrado mayor se administra vitamina K IV más concentrado de complejo protrombínico. Interacciones frecuentes: antibióticos, amiodarona, alcohol y dieta rica en vitamina K.",
  f="ACCP/CHEST, tratamiento antitrombótico (2021); ESC, fibrilación auricular (2024); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cardiologia", cat=None, tema="Shock obstructivo por taponamiento pericárdico", año=2018, ext=False,
  e="¿Qué tipo de shock puede originar el taponamiento pericárdico?",
  o=["Neurogénico.", "Hipovolémico.", "Distributivo.", "Obstructivo.", "Cardiogénico."], k="D",
  c="El taponamiento pericárdico es una causa de shock obstructivo: el líquido en el saco pericárdico comprime las cavidades cardiacas, impide su llenado diastólico y reduce el gasto cardiaco, pese a que la función contráctil intrínseca del corazón es normal. Otras causas de shock obstructivo son el neumotórax a tensión, la embolia pulmonar masiva y la hipertensión pulmonar grave. El shock cardiogénico implica fallo de la bomba (infarto, miocardiopatía, arritmia); el hipovolémico, pérdida de volumen; el distributivo (séptico, anafiláctico, neurogénico), vasodilatación. En el taponamiento se ve hipotensión, ingurgitación yugular y ruidos apagados (tríada de Beck), pulso paradójico, y en la ecocardiografía colapso de cavidades derechas. El manejo es drenaje inmediato (pericardiocentesis guiada por eco o ventana pericárdica) y, mientras tanto, volumen intravenoso y evitar la ventilación con presión positiva elevada.",
  f="ESC, enfermedades del pericardio (2015); ATLS 11.ª ed. (2025); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cardiologia", cat=None, tema="Hidroclorotiazida en dislipidemia", año=2018, ext=False,
  e="¿Cuál es el medicamento que está contraindicado en pacientes con dislipidemia e hipertensión arterial?",
  o=["Enalapril.", "Alfametildopa.", "Amlodipino.", "Valsartán.", "Hidroclorotiazida."], k="E",
  c="Las tiazidas, y también los betabloqueantes no selectivos, pueden empeorar el perfil metabólico: la hidroclorotiazida en dosis altas eleva el colesterol total, el LDL y los triglicéridos, además de causar hipopotasemia, hiponatremia, hiperuricemia, hipercalcemia e intolerancia a la glucosa. Por eso se evita (o se usa en dosis bajas, 12,5-25 mg) cuando hay dislipidemia grave, gota o diabetes mal controlada. Los IECA (enalapril), ARA II (valsartán) y los calcioantagonistas (amlodipino) son metabólicamente neutros; la alfametildopa es neutra y de elección en el embarazo. En la práctica actual, las tiazidas siguen siendo una de las clases de primera línea (clortalidona e indapamida son más potentes), y se vigilan los electrolitos. La palabra «contraindicado» de la pregunta debe entenderse como «la menos recomendable», no como una contraindicación absoluta.",
  f="ACC/AHA, guía de hipertensión arterial (2025); ESC, guía de hipertensión arterial (2024); Katzung Farmacología Básica y Clínica 15.ª ed.",
  nota="Pregunta de redacción discutible (contraindicación relativa); se mantiene la clave del libro.")

Q(a="cirugia", cat=None, tema="Primera medida ante un paro cardiaco inminente", año=2018, ext=False,
  e="Varón de 65 años, ingresa a emergencia por presentar hace 10 minutos precordialgia intensa en forma brusca, angustia, diaforesis profusa y pérdida de conocimiento. Antecedente: diabético e hipertenso hace 10 años no controlado. Examen: mal estado general, inconsciente, cianótico y jadeante. Se confirma inminente paro cardiaco. ¿Cuál es la primera medida a realizar?",
  o=["Golpes precordiales con puño cerrado.", "Administración de vasopresores.", "Desfibrilación inmediata.", "Solicitar CPK, troponina.", "Cuidar la función respiratoria."], k="E",
  c="Un paciente con dolor torácico intenso, inconsciente, cianótico y jadeante pero con pulso presente está en una situación de peri-paro: todavía no está en paro cardiaco. La prioridad es la valoración ABC (vía aérea, ventilación, circulación): asegurar y despejar la vía aérea, administrar oxígeno y ventilar, monitorizar con electrocardiograma, establecer un acceso venoso y tener el desfibrilador listo. Los golpes precordiales ya no se recomiendan de rutina (solo en un paro presenciado y monitorizado sin desfibrilador), los vasopresores se reservan para el paro o el shock, la desfibrilación inmediata se hace si hay fibrilación ventricular o taquicardia ventricular sin pulso, y los marcadores no cambian la conducta inmediata. En cuanto se confirme el paro (sin pulso), se cambia a la secuencia CAB de reanimación cardiopulmonar de alta calidad: compresiones de 5-6 cm a 100-120 por minuto.",
  f="AHA, Soporte Vital Cardiovascular Avanzado (actualización 2025); ERC, guías de reanimación (2021)")

Q(a="nefrologia", cat=None, tema="Antihipertensivo en enfermedad renal con hematuria", año=2019, ext=False,
  e="Varón de 68 años, 60 kg de peso, refiere presentar hace 3 meses cefalea global en forma episódica, astenia, hiporexia, edema palpebral; con antecedente de hipertensión arterial no controlada. Funciones vitales: PA: 170/100 mmHg, FC: 62 x min, FR: 20 x min, afebril. Laboratorio: Hto: 28 %, creatinina: 3 mg/dL, urea: 68 mg/dL. Sedimento urinario: leucocitos: 3-5/campo, hematíes: 15-18/campo. ¿Qué antihipertensivo elegiría?",
  o=["Enalapril.", "Atenolol.", "Reserpina.", "Nifedipino.", "Hidroclorotiazida."], k="A",
  c="Un paciente hipertenso con enfermedad renal crónica (creatinina 3 mg/dL, anemia, edema, hematuria) y probable daño glomerular necesita un fármaco que reduzca la presión intraglomerular y la proteinuria: los IECA (enalapril) y los ARA II son de primera línea, con vigilancia de creatinina y potasio a la semana de iniciar o aumentar la dosis; se acepta un aumento de creatinina de hasta el 30 %. Se suspenden si la creatinina sube más, hay hiperpotasemia mayor de 5,5 mEq/L o estenosis bilateral de arterias renales. Las tiazidas pierden eficacia con filtrado < 30 mL/min (se prefieren los diuréticos de asa), el atenolol se acumula en insuficiencia renal, la reserpina es de segunda línea y el nifedipino puede añadirse como segundo fármaco. La meta es PA < 130/80 mmHg. Los iSGLT2 y la finerenona se añaden en enfermedad renal diabética según KDIGO 2024.",
  f="KDIGO, hipertensión arterial en enfermedad renal crónica (2021) y ERC (2024); ACC/AHA, guía de hipertensión (2025)")

Q(a="cirugia", cat=None, tema="Herida precordial penetrante: taponamiento cardiaco", año=2019, ext=False,
  e="Varón de 23 años llega a emergencia con herida por arma blanca en región precordial, con dolor y dificultad respiratoria. Examen: PA: 100/60 mmHg, FC: 110 x min, SatO₂: 95 %. Ingurgitación yugular moderada. Herida punzocortante penetrante en región precordial, ruidos cardiacos disminuidos de intensidad. Pulmones: murmullo vesicular disminuido en ambos hemitórax sin estertores. PVC: 15 cm de agua. ¿Cuál es el diagnóstico probable?",
  o=["Taponamiento cardiaco.", "Neumotórax a tensión.", "Infarto agudo de miocardio.", "Ruptura ventricular.", "Embolia pulmonar."], k="A",
  c="Una herida penetrante en la «zona de peligro» precordial (entre las líneas medioclaviculares, del borde costal a la fúrcula) con hipotensión, ingurgitación yugular, ruidos cardiacos apagados y presión venosa central elevada configura la tríada de Beck del taponamiento cardiaco: la sangre acumulada en el saco pericárdico (tan poco como 100-200 mL) comprime el corazón. En el neumotórax a tensión también hay ingurgitación yugular y shock, pero el hemitórax es hipersonoro, el murmullo está abolido de un lado y la tráquea se desvía. En el trauma, la ecografía FAST con ventana pericárdica confirma el hemopericardio en segundos; en inestabilidad se hace toracotomía o esternotomía de urgencia para drenar y reparar el defecto cardiaco; la pericardiocentesis queda como medida temporal. Volumen IV mientras tanto aumenta la precarga.",
  f="ATLS, 11.ª ed. (2025); Schwartz Principios de Cirugía 11.ª ed.")

Q(a="ciencias_basicas", cat="Fisiología", tema="Determinante de la precarga", año=2019, ext=False,
  e="¿Qué parámetro representa uno de los determinantes de la precarga en la curva presión-volumen del ventrículo izquierdo?",
  o=["Presión al final de la sístole.", "Volumen al inicio de la diástole.", "Presión al inicio de la diástole.", "Volumen al final de la sístole.", "Volumen al final de la diástole."], k="E",
  c="La precarga es la tensión o estiramiento de la fibra miocárdica justo antes de contraerse; en la clínica se aproxima por el volumen (y la presión) telediastólico del ventrículo, es decir, el volumen al final de la diástole. En el asa presión-volumen, la precarga corresponde al punto donde se cierra la válvula mitral, y se relaciona con el retorno venoso y con la distensibilidad ventricular. La poscarga es la resistencia que debe vencer el ventrículo para eyectar (presión aórtica o tensión de la pared durante la sístole). Según la ley de Frank-Starling, un mayor volumen telediastólico aumenta la fuerza de contracción hasta un límite. Se reduce la precarga con diuréticos y nitratos, y se aumenta con volumen. La presión de enclavamiento capilar pulmonar medida con catéter de Swan-Ganz la estima.",
  f="Guyton y Hall Tratado de Fisiología Médica 14.ª ed.; Braunwald Tratado de Cardiología 12.ª ed.")

Q(a="cardiologia", cat=None, tema="Meta de presión diastólica en emergencia hipertensiva", año=2019, ext=False,
  e="Varón de 56 años, hipertenso con tratamiento irregular, acude a emergencia por cefalea tipo opresivo, náuseas y alteraciones visuales. Examen: PA 200/140 mmHg, FC 102 x min, saturación de 98 %, fondo de ojo: retinopatía hipertensiva grado III; pasa a Shock Trauma donde se inicia labetalol endovenoso. ¿A qué valor se debe disminuir la presión diastólica en mmHg?",
  o=["115 a 120.", "100 a 105.", "110 a 115.", "80 a 90.", "90 a 95."], k="B",
  c="La emergencia hipertensiva es una elevación grave de la presión (generalmente > 180/120 mmHg) con daño agudo de órgano blanco: encefalopatía, retinopatía grado III-IV, edema pulmonar, síndrome coronario agudo, disección aórtica o eclampsia. Se trata en cuidados intensivos con fármacos intravenosos (labetalol, nicardipino, nitroprusiato, clevidipino) y monitorización continua. La meta general es disminuir la presión arterial media un 20-25 % en la primera hora y luego a 160/100-110 mmHg en 2 a 6 horas y a lo normal en 24-48 horas, porque un descenso brusco produce isquemia cerebral, coronaria y renal al sobrepasar la autorregulación. Con una diastólica de 140 mmHg, una reducción del 25 % la llevaría a 100-105 mmHg. Excepciones: disección aórtica (PAS < 120 en 20 minutos) y accidente cerebrovascular isquémico (reducir solo si > 220/120 o antes de trombólisis).",
  f="ACC/AHA, guía de hipertensión arterial (2025); ESC, guía de hipertensión arterial (2024); Harrison Principios de Medicina Interna 22.ª ed.")

Q(a="cardiologia", cat=None, tema="Pronóstico del síndrome posparo cardiaco", año=2019, ext=False,
  e="¿Cuál es el factor pronóstico más importante en el síndrome postparo cardiaco?",
  o=["Hipotermia periférica.", "Bradiarritmia.", "Encefalopatía anóxica.", "Isquemia coronaria.", "Hipoperfusión periférica."], k="C",
  c="El síndrome posparo cardiaco incluye lesión cerebral hipóxico-isquémica, disfunción miocárdica, respuesta sistémica de isquemia-reperfusión y la patología que causó el paro. La lesión cerebral es la principal causa de morbimortalidad y la que determina el pronóstico neurológico, porque las neuronas de la corteza, el hipocampo, el cerebelo y el tálamo son muy sensibles a la isquemia y al daño por reperfusión. Manejo: control de la temperatura (entre 32 y 37,5 °C, evitando la fiebre por al menos 72 horas), SatO₂ 94-98 %, PaCO₂ normal, PA media ≥ 65 mmHg, coronariografía precoz si hay elevación del ST, y no predecir el pronóstico antes de las 72 horas del retorno de la circulación espontánea, con un enfoque multimodal (examen clínico, EEG, potenciales evocados, neuroimagen y neuronas específicas séricas).",
  f="AHA, cuidados posparo cardiaco (actualización 2025); ERC-ESICM, cuidados posreanimación (2021)")

Q(a="cardiologia", cat=None, tema="Inicio de elevación de la troponina", año=2019, ext=False,
  e="Después de iniciados los síntomas de infarto agudo de miocardio, ¿dentro de qué tiempo en horas se produce el inicio del aumento de las troponinas?",
  o=["2.", "4.", "6.", "3.", "1."], k="B",
  c="Tras la necrosis del cardiomiocito, las troponinas I y T se liberan al plasma y comienzan a subir entre las 3 y 4 horas, alcanzan su pico a las 12-48 horas y permanecen elevadas durante 7-14 días (troponina I) o más (troponina T). La CK-MB se eleva a las 3-6 horas y se normaliza en 48-72 horas; la mioglobina sube en 1-2 horas pero es poco específica. Con ensayos de alta sensibilidad la elevación se detecta ya en la primera hora, por lo que los algoritmos ESC de 0/1 h y 0/2 h permiten descartar o confirmar el infarto con una segunda muestra. El libro adopta 4 horas como el comienzo clásico de la curva. Recuerda: el diagnóstico exige elevación de troponina por encima del percentil 99 con un patrón de subida o bajada, más evidencia de isquemia.",
  f="ESC, síndromes coronarios agudos (2023); Cuarta Definición Universal del Infarto (2018)",
  nota="La clave extraída automáticamente era E; la imagen del libro indica B (4 horas).")

Q(a="cardiologia", cat=None, tema="Taquicardia supraventricular: adenosina tras maniobras vagales", año=2019, ext=False,
  e="Mujer de 30 años, acude a emergencia por palpitaciones, dolor precordial y ansiedad. Examen: PA: 110/70 mmHg, FC: 210 x min, FR: 24 x min, SatO₂: 97 %. EKG: complejos QRS angostos, regulares, P retrógrada luego del QRS. Luego de realizar maniobras vagales sin respuesta favorable, ¿cuál es el fármaco de elección?",
  o=["Metoprolol.", "Lanatósido.", "Adenosina.", "Amiodarona.", "Verapamilo."], k="C",
  c="El electrocardiograma con QRS estrecho, regular y onda P retrógrada después del QRS (pseudo-r' en V1 o pseudo-S en derivaciones inferiores) es típico de una taquicardia por reentrada intranodal (AVNRT), la causa más frecuente de taquicardia supraventricular paroxística en mujeres jóvenes. Si las maniobras vagales fracasan, el fármaco de elección es la adenosina en bolo rápido (6 mg, repetible con 12 mg) seguida de un lavado salino, que bloquea el nodo auriculoventricular transitoriamente y revierte la taquicardia en > 90 %. Si no responde se usa verapamilo, diltiazem o un betabloqueante, y con inestabilidad (hipotensión, dolor anginoso, edema pulmonar) la cardioversión eléctrica sincronizada. A largo plazo se puede ofrecer ablación con catéter, curativa en > 95 %. La adenosina está contraindicada en asma grave y en fibrilación auricular preexcitada.",
  f="AHA/ACC/HRS, guía de taquicardia supraventricular (2015); ESC, taquicardia supraventricular (2019); AHA, SVCA (actualización 2025)",
  nota="Pregunta repetida (RM 2015 y RM 2019).")

Q(a="nefrologia", cat=None, tema="Nefropatía diabética incipiente: elección del fármaco", año=2019, ext=False,
  e="Varón de 45 años, asintomático, acude para evaluación de función renal. Antecedentes: HTA hace 2 meses sin tratamiento, DM2 hace 5 años. Examen: PA: 160/100 mmHg, resto no contributorio. Laboratorio: depuración de creatinina: 100 mL/min. Proteinuria de 24 h: 500 mg en dos oportunidades. ¿Cuál es el fármaco de elección?",
  o=["Metildopa.", "Amlodipino.", "Hidroclorotiazida.", "Enalapril.", "Furosemida."], k="D",
  c="Un diabético hipertenso con proteinuria persistente (500 mg/24 h son valores de albuminuria moderada-grave) tiene nefropatía diabética incipiente y se beneficia sobre todo de un IECA o un ARA II, porque reducen la presión intraglomerular al dilatar la arteriola eferente, disminuyen la proteinuria y retrasan la progresión a enfermedad renal terminal. Las guías KDIGO, ADA y ACC/AHA recomiendan IECA/ARA II como primera línea cuando hay albuminuria; la meta de PA es < 130/80 mmHg y se añaden después amlodipino o una tiazida (clortalidona). Se agregan iSGLT2 (empagliflozina, dapagliflozina) y, si persiste albuminuria, finerenona; metformina si el filtrado es > 30 mL/min. Se controlan creatinina y potasio a los 7-14 días. Los IECA están contraindicados en el embarazo, el angioedema previo y la estenosis bilateral de arterias renales.",
  f="ADA, estándares de atención en diabetes (2026); KDIGO, diabetes y enfermedad renal crónica (2022) y ERC (2024); ACC/AHA, hipertensión (2025)")

Q(a="cirugia", cat=None, tema="Apendicitis aguda: signo de Horn", año=2014, ext=False,
  e="Varón de 20 años, con dolor abdominal de inicio súbito que luego se localiza en fosa ilíaca derecha. Examen: Blumberg (+), dolor al traccionar suavemente el testículo derecho. No leucocitosis. ¿Cuál es el diagnóstico?",
  o=["Apendicitis aguda.", "Litiasis renal.", "Infección urinaria.", "Torsión testicular.", "Orquiepididimitis."], k="A",
  c="El dolor que se inicia en la región periumbilical o epigástrica y migra a la fosa ilíaca derecha, con signo de Blumberg (dolor al descomprimir) positivo, es la presentación clásica de la apendicitis aguda. El signo de Horn (dolor en el testículo derecho al traccionar suavemente el cordón espermático) es una manifestación de irritación peritoneal local por la proximidad del apéndice con el cordón. Los testículos están normales en la apendicitis; en la torsión testicular el dolor es escrotal, súbito e intenso y el testículo está elevado; la litiasis ureteral produce cólico lumbar irradiado a ingle con hematuria. La ausencia de leucocitosis no descarta apendicitis. Puntajes útiles: Alvarado (≥ 7 apoya) y AIR; la ecografía en niños y la TC en adultos mejoran el diagnóstico. Tratamiento: apendicectomía laparoscópica; en casos no complicados se puede considerar antibióticos (ensayo CODA 2020).",
  f="WSES, guía de apendicitis aguda (2020); Sabiston Tratado de Cirugía 21.ª ed.")

Q(a="cirugia", cat=None, tema="Síntoma clave cuya ausencia hace dudar de apendicitis", año=2014, ext=False,
  e="¿Cuál de los siguientes síntomas, al estar ausente, pone en duda el diagnóstico de apendicitis aguda?",
  o=["Anorexia.", "Malestar general.", "Náuseas y vómitos.", "Fiebre.", "Constipación."], k="A",
  c="La anorexia es el síntoma más constante de la apendicitis aguda: está presente en casi el 90-95 % y se dice que «si el paciente tiene hambre, hay que dudar del diagnóstico». Los síntomas ocurren típicamente en la secuencia de Murphy: dolor epigástrico o periumbilical, anorexia, náuseas o vómitos (que aparecen después del dolor, nunca antes: si el vómito precede al dolor se piensa en gastroenteritis), migración del dolor a la fosa ilíaca derecha y fiebre baja (37,5-38 °C). La fiebre alta suele indicar perforación. La constipación y la diarrea pueden estar presentes o ausentes. El puntaje de Alvarado (MANTRELS) asigna 1 punto a anorexia, 1 a náuseas/vómitos, 2 a dolor en fosa ilíaca derecha, 2 a leucocitosis, 1 a desviación izquierda, 1 a fiebre, 1 a migración y 1 a rebote.",
  f="WSES, guía de apendicitis aguda (2020); Sabiston Tratado de Cirugía 21.ª ed.")

Q(a="cirugia", cat=None, tema="Factor asociado al vólvulo cecal", año=2014, ext=False,
  e="¿Cuál de los siguientes factores está más asociado a la producción del vólvulo cecal?",
  o=["Malrotación.", "Estreñimiento.", "Parasitosis crónica.", "Uso de psicotrópicos.", "Mesenterio largo."], k="A",
  c="El vólvulo cecal ocurre cuando el ciego (o el ciego y el colon ascendente) se tuerce sobre su eje mesentérico y produce una obstrucción en asa cerrada con riesgo de isquemia y perforación. El factor predisponente más importante es la falta de fijación del ciego por malrotación intestinal (el ciego queda móvil y con un mesenterio largo, hallazgo presente en ≈ 10-25 % de la población). Otros factores: cirugía abdominal previa, embarazo, estreñimiento crónico y dieta rica en fibra que alarga el colon. En la radiografía de abdomen se ve el signo del «grano de café» o del «ciego en coma» desplazado al cuadrante superior izquierdo. A diferencia del vólvulo sigmoideo, no se puede reducir con endoscopía; el tratamiento es quirúrgico (hemicolectomía derecha, o cecopexia si el intestino es viable).",
  f="Schwartz Principios de Cirugía 11.ª ed.; Sabiston Tratado de Cirugía 21.ª ed.")

Q(a="cirugia", cat=None, tema="Causa más frecuente de obstrucción intestinal posoperatoria", año=2014, ext=True,
  e="¿Cuál es la causa más frecuente de obstrucción intestinal en un paciente con antecedente de cirugía abdominal?",
  o=["Hernia crural estrangulada.", "Bridas y adherencias.", "Hernia inguinal incarcerada.", "Vólvulo yeyunal.", "Intususcepción."], k="B",
  c="Las adherencias y bridas posoperatorias son la causa más frecuente de obstrucción del intestino delgado en general (55-75 %) y la primera causa cuando hay antecedente de cirugía abdominal o pélvica (apendicectomía, cirugía colorrectal, ginecológica). Se forman por la reparación fibrosa del peritoneo, y pueden producir obstrucción semanas o décadas después. Las hernias de la pared abdominal son la segunda causa y los tumores, la tercera. El cuadro típico es el dolor cólico, vómitos, distensión y ausencia de gases y heces, con niveles hidroaéreos en la radiografía. El tratamiento inicial de una obstrucción parcial es conservador (ayuno, sonda nasogástrica, hidratación, corrección electrolítica y administración de contraste hidrosoluble, que es diagnóstico y terapéutico); la cirugía es urgente si hay signos de estrangulación (fiebre, peritonismo, leucocitosis, acidosis láctica), obstrucción completa o falta de mejoría en 48-72 horas.",
  f="WSES, obstrucción adhesiva del intestino delgado (2018); Sabiston Tratado de Cirugía 21.ª ed.")

Q(a="cirugia", cat=None, tema="Síndrome de Ogilvie", año=2014, ext=False,
  e="La seudoobstrucción del colon, con dilatación masiva sin una obstrucción mecánica, se observa con mayor frecuencia en pacientes hospitalizados y se relaciona con el uso sostenido de:",
  o=["Narcóticos.", "Antipiréticos.", "Diuréticos.", "Hipoglicemiantes.", "Hipotensores."], k="A",
  c="La seudoobstrucción aguda del colon (síndrome de Ogilvie) es una dilatación masiva del colon, sobre todo del ciego, sin obstrucción mecánica. Aparece en pacientes graves, tras cirugía o trauma, con sepsis, trastornos electrolíticos (hipopotasemia, hipomagnesemia, hipocalcemia) y con el uso de fármacos que enlentecen el tránsito: opioides (narcóticos), anticolinérgicos, antidepresivos tricíclicos, antipsicóticos y bloqueantes de canales de calcio. El riesgo de perforación aumenta si el ciego mide más de 12 cm o la dilatación dura más de 6 días. El tratamiento inicial es de soporte: ayuno, sonda nasogástrica y rectal, corrección de electrolitos, suspender los fármacos causantes y, si el ciego supera 10-12 cm sin respuesta, neostigmina IV (2 mg) con monitorización cardiaca y atropina disponible, o descompresión colonoscópica. Es una contraindicación de la neostigmina el asma grave o la obstrucción mecánica.",
  f="Sabiston Tratado de Cirugía 21.ª ed.; Schwartz Principios de Cirugía 11.ª ed.")

Q(a="cirugia", cat=None, tema="Alteraciones hidroelectrolíticas en la obstrucción intestinal alta", año=2014, ext=False,
  e="¿Cuál es el trastorno hidroelectrolítico y ácido-base más frecuente en la obstrucción intestinal proximal?",
  o=["Hipopotasemia y alcalosis metabólica.", "Hiponatremia y alcalosis metabólica.", "Hipopotasemia y acidosis metabólica.", "Hipernatremia y alcalosis respiratoria.", "Hipocalcemia y acidosis metabólica."], k="A",
  c="En la obstrucción intestinal alta (píloro o intestino delgado proximal) predominan los vómitos copiosos, que eliminan jugo gástrico rico en ácido clorhídrico y potasio. La pérdida de protones y cloro deja un exceso de bicarbonato (alcalosis metabólica hipoclorémica), y la hipovolemia activa el sistema renina-angiotensina-aldosterona, que retiene sodio a costa de eliminar potasio y protones en la orina (aciduria paradójica), con lo que se agrava la hipopotasemia. En la obstrucción distal con isquemia, estrangulación o sepsis, en cambio, predomina la acidosis metabólica con lactato elevado. El tratamiento es reponer volumen con solución salina isotónica con potasio, que corrige la hipovolemia y la hipocloremia, y descomprimir con sonda nasogástrica. Evalúa la gasometría y los electrolitos en el ingreso.",
  f="Sabiston Tratado de Cirugía 21.ª ed.; Harrison Principios de Medicina Interna 22.ª ed.")
